- Budget: {{ $json.budget || 'Not provided' }}
- Timeline: {{ $json.timeline || 'Not provided' }}
- Property interest: {{ $json.property_interest || 'Not provided' }}
- Tags: {{ $json.tags || 'None' }}
- Message: {{ $json.message || 'No message' }}
- Email: {{ $json.email ? 'Provided' : 'Not provided' }}
- Phone: {{ $json.phone ? 'Provided' : 'Not provided' }}

Return ONLY valid JSON, no markdown, no code fences:
{
  "score": <number 1-10>,
  "tier": "<Hot|Warm|Cold>",
  "reasoning": "<one sentence>",
  "recommended_action": "<one sentence next step for the sales agent>"
}

