const agentOutput = $json.output || '';
const leadData = $('Normalize Lead Fields').first().json;
let scoreData = { score: 5, reasoning: 'Score unavailable, review this lead manually.', recommended_action: 'Review this lead manually.' };
try {
  const cleaned = agentOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1) { scoreData = JSON.parse(cleaned.substring(start, end + 1)); }
} catch (e) {}
const parsed = parseInt(scoreData.score, 10);
const score = Math.min(10, Math.max(1, isNaN(parsed) ? 5 : parsed));
const tier = score >= 8 ? 'Hot' : score >= 5 ? 'Warm' : 'Cold';
return { json: { ...leadData, score, tier, reasoning: scoreData.reasoning || '', recommended_action: scoreData.recommended_action || '', scored_at: new Date().toISOString() } };

